-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.priest.dps.Name"] = "Danni"
L["rm.era.priest.dps.Description"] = "Danni dal livello 1 al 60, e la scelta predefinita del Sacerdote ogni volta che la rotazione integrata da guaritore non si applica (da solo, Ombra o ancora senza talenti). Forma d'Ombra una volta appresa; prima di un ingaggio uno scudo quando giochi da solo, poi Fuoco Sacro (senza Forma d'Ombra), Detonazione Mentale o Punizione. Parola d'Ombra: Dolore una volta per ogni bersaglio che sopravvivrà, Detonazione Mentale appena pronta, Flagello Mentale come riempitivo (Punizione ed Esplosione Sacra prima di averlo), e la bacchetta su un bersaglio in punto di morte o quando il mana scarseggia mentre giochi da solo. Abbraccio Vampirico e Piaga Divoratrice nei combattimenti lunghi, mai in incursione. Promemoria: Fuoco Interiore, Fermezza, effetti benefici razziali, Concentrazione Interiore con Detonazione Mentale, Urlo Psichico quando due nemici ti raggiungono a metà salute, Trasparenza quando il tuo bersaglio si rivolta contro di te, Preghiera Disperata. Scelta del bersaglio, multi-DoT e uso dei gradi inferiori restano a te."
L["rm.era.priest.dps.simulator.Name"] = "Danni (incursione Non Morto di simulatore)"
L["rm.era.priest.dps.simulator.Description"] = "La priorità di danni consigliata con la scelta da incursione di simulatore per i sacerdoti Non Morti: Concentrazione Interiore viene spesa su Piaga Divorante invece che su Detonazione Mentale, e Piaga Divorante viene lanciata anche in incursione, quindi usala solo dove la tua incursione ha posti liberi per le penalità. Niente Abbraccio Vampirico. Un'alternativa alla rotazione integrata consigliata di danni, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.era.priest.dps.warcrafttavern.Name"] = "Danni (economia con la bacchetta di Warcraft Tavern)"
L["rm.era.priest.dps.warcrafttavern.Description"] = "Lo stile di livellamento con pochi tempi morti di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata di danni, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Da solo: Detonazione Mentale per ingaggiare, Parola d'Ombra: Dolore una volta, di nuovo Detonazione Mentale solo finché il bersaglio è sopra il 30%, e la bacchetta tra una Detonazione Mentale e l'altra invece di Punizione o Flagello Mentale. Nessuno scudo automatico prima degli ingaggi. In gruppo: Parola d'Ombra: Dolore, Detonazione Mentale, Flagello Mentale. Stessi promemoria della rotazione integrata consigliata."
L["rm.era.priest.healer.Name"] = "Guaritore"
L["rm.era.priest.healer.Description"] = "Scelta in gruppo quando Sacro o Disciplina è il tuo albero dei talenti principale. Cura l'unità amica che hai come bersaglio: Parola del Potere: Scudo sotto il 30%, Cura Rapida sotto il 40%, dissoluzioni, Preghiera di Cura quando tre membri del tuo gruppo sono feriti, Cura Maggiore (Cura o Cura Inferiore prima di averla appresa) sotto metà della salute, Rinnovamento in movimento o con danni leggeri, poi Cura di grado 3 come rabbocco efficiente. Fuori dal combattimento propone Fermezza sul tuo bersaglio. Un bersaglio nemico riceve Parola d'Ombra: Dolore e Punizione. Promemoria: Fuoco Interiore, Fermezza, Spirito Divino, Concentrazione Interiore, Preghiera Disperata; Infusione di Potere è disattivata per impostazione predefinita. La scelta di chi curare e l'uso dei gradi inferiori restano a te."
L["rm.forever.priest.dps.Name"] = "Ombra e danni da solo"
L["rm.forever.priest.dps.Description"] = "Ombra, e il gioco in solitaria di ogni Sacerdote, dal livello 1 al 60; la scelta predefinita del Sacerdote di Forever. Ingaggia con Parola del Potere: Scudo (da solo) e Detonazione Mentale (Fuoco Sacro per Sacro e Disciplina, Punizione prima di Detonazione Mentale). Poi Forma d'Ombra una volta appresa, la tua Parola d'Ombra: Dolore e Piaga Divorante, Detonazione Mentale, Fuoco Sacro seguito da Penitenza per Disciplina, Flagello Mentale in Forma d'Ombra; da solo prima di Forma d'Ombra, Nova Sacra contro tre nemici con Proposito Sacro, poi la bacchetta (Punizione se non ne hai una). In movimento: Dolore, Piaga. Promemoria: Fuoco Interiore, Fermezza, Spirito Divino, effetti benefici razziali, Abbraccio Vampirico, Concentrazione Interiore, Silenzio, Luce di Elune; Urlo Psichico è disattivato per impostazione predefinita. Su Forever salute e mana sono nascosti agli addon, quindi finire con Parola d'Ombra: Morte, curarti e Sacrificio Oscuro sono una tua scelta. Costruita da guide della beta di livello 30; il gioco in Forma d'Ombra segue Mobalytics."
L["rm.forever.priest.dps.mobalytics.Name"] = "Livellamento con DoT e bacchetta (Mobalytics)"
L["rm.forever.priest.dps.mobalytics.Description"] = "Lo stile di livellamento di Mobalytics, un'alternativa alla rotazione integrata consigliata Ombra, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Detonazione Mentale e Fuoco Sacro solo sui mostri difficili (élite, o di due livelli sopra di te), la tua Parola d'Ombra: Dolore e Piaga Divorante, poi la bacchetta (Punizione se non ne hai una). Da Forma d'Ombra: Detonazione Mentale, Dolore, Piaga, Flagello Mentale. Scudo e Rinnovamento su di te tra un ingaggio e l'altro, Cura Malattia su di te. Su Forever salute e mana sono nascosti agli addon, quindi curarti è una tua scelta. Distribuire Dolore su più mostri spetta a te."
L["rm.forever.priest.healer.Name"] = "Cure Disciplina e Sacro"
L["rm.forever.priest.healer.Description"] = "Cure di gruppo una volta che Disciplina o Sacro è il tuo albero dei talenti principale e non conosci Forma d'Ombra. Cura il tuo attuale bersaglio amico: prima dell'ingaggio Parola del Potere: Scudo, Preghiera di Guarigione e Rinnovamento; Dissolvi Magia e Abolisci Malattia o Cura Malattia; Preghiera di Guarigione; Nova Sacra con Proposito Sacro; Penitenza; Rinnovamento quando manca; Cura (Cura Inferiore prima di essa). Su un nemico: Parola d'Ombra: Dolore, Fuoco Sacro, Penitenza, Punizione, bacchetta. Promemoria: Fuoco Interiore, Fermezza, Spirito Divino, Infusione di Potere su un altro giocatore, Concentrazione Interiore in combattimento e gli incantesimi razziali. Su Forever salute e mana sono nascosti agli addon, quindi il bersaglio che scegli è l'unico segno di chi ha bisogno di cure; le cure d'emergenza, Preghiera di Cura, Cura Combinata, Cura Superiore e Cura Rapida, Preghiera Disperata e Sacrificio Oscuro sono una tua scelta. Scegli tu chi curare e il grado; un guaritore Disciplina prima di Penitenza (20–29) la seleziona a mano."
L["rm.mop.priest.discipline.Name"] = "Consigliata"
L["rm.mop.priest.discipline.Description"] = "Cure Disciplina dal livello 10 al 90, scelta nella specializzazione Disciplina. Prendi come bersaglio un alleato per curarlo: Parola del Potere: Scudo quando è basso di salute, prima dell'ingaggio e circa ogni 12 secondi per Estasi; Cura Rapida con Eruzione di Luce; Penitenza; Cura Rapida quando è molto basso di salute; Cura Combinata quando siete feriti entrambi; Preghiera di Guarigione; Preghiera di Cura e il tuo talento di sesto livello quando tre alleati sono feriti; Cura Superiore; Rinnovamento in movimento; Cura per completare. Durante Involucro Spirituale suggerisce Preghiera di Cura o Cura Superiore. Prendi come bersaglio un nemico per curare tramite Espiazione: Penitenza, Parola del Potere: Conforto o Fuoco Sacro, il tuo talento di sesto livello sui gruppi di nemici, Parola d'Ombra: Dolore quando giochi da solo, Punizione. Promemoria: Fuoco Interiore, Fermezza, Arcangelo a cinque cumuli di Evangelismo, Concentrazione Interiore, Soppressione del Dolore su un bersaglio in punto di morte, Spirito d'Ombra o Plagiamente per il mana, Infusione di Potere, Preghiera Disperata. Lasciati a te: chi curare, il tempismo di Involucro Spirituale (un promemoria che puoi attivare), Parola del Potere: Barriera, Transizione del Vuoto e i cumuli di Grazia sul difensore."
L["rm.mop.priest.holy.Name"] = "Consigliata"
L["rm.mop.priest.holy.Description"] = "Cure Sacro dal livello 10 al 90, scelta nella specializzazione Sacro. Prendi come bersaglio un alleato per curarlo: Parola Sacra: Serenità in Chakra: Serenità; Parola del Potere: Scudo solo quando sta per morire; Cura Rapida con Eruzione di Luce; Preghiera di Guarigione; Cura Rapida quando è molto basso di salute; Cura Combinata quando siete feriti entrambi; in gruppo con tre alleati feriti, Circolo di Guarigione, Parola Sacra: Santuario in Chakra: Santuario, il tuo talento di sesto livello e Preghiera di Cura; Rinnovamento; Cura Superiore quando è basso di salute o a due cumuli di Provvidenza; Cura. Prendi come bersaglio un nemico per infliggere danni: Parola Sacra: Castigo, Parola del Potere: Conforto o Fuoco Sacro, Parola d'Ombra: Dolore quando giochi da solo, il tuo talento di sesto livello sui gruppi di nemici, Punizione. Un chakra vuoto viene riempito per te (Santuario in incursione, Serenità in gruppo, Castigo da solo) e mai cambiato. Promemoria: Fuoco Interiore, Fermezza, Spirito Custode su un bersaglio in punto di morte, Inno Divino quando cinque alleati sono gravemente feriti, Spirito d'Ombra o Plagiamente per il mana, Infusione di Potere, Preghiera Disperata. Lasciati a te: chi curare, il posizionamento di Parola Sacra: Santuario, Pozzo di Luce e Transizione del Vuoto."
L["rm.mop.priest.holy.icyveins.Name"] = "Cure d'emergenza per ultime (Icy Veins)"
L["rm.mop.priest.holy.icyveins.Description"] = "Disattivata per impostazione predefinita. L'ordine Sacro di Icy Veins, scelto in base al tuo chakra. In Chakra: Santuario: Parola Sacra: Santuario quando tre alleati sono feriti, Rinnovamento, Circolo di Guarigione, Preghiera di Guarigione, Preghiera di Cura, poi Cura Combinata e Cura Rapida solo nelle emergenze. Altrimenti: Rinnovamento, Parola Sacra: Serenità, Preghiera di Guarigione, Cura Maggiore, Cura, Cura Combinata, Cura Rapida, Parola del Potere: Scudo per ultima, e Cura Rapida come riempitivo prima di apprendere Cura. Stesso cambio, promemoria ed elenco dei danni della rotazione integrata Sacro consigliata; per usarla attivala e disattiva l'altra."
L["rm.mop.priest.shadow.Name"] = "Consigliata"
L["rm.mop.priest.shadow.Description"] = "Danni Ombra dal livello 10 al 90, scelta nella specializzazione Ombra. Apre con Aculeo Mentale, Detonazione Mentale o i tuoi DoT. Piaga Divorante a tre Globi dell'Ombra (quando Detonazione Mentale è pronta o mancano ancora sei secondi), Detonazione Mentale, Parola d'Ombra: Morte sotto il 20% di salute, Flagello Mentale mentre la tua Piaga Divorante è attiva se hai scelto Conforto e Pazzia, Parola d'Ombra: Dolore e Tocco Vampirico rinnovati verso la fine su un bersaglio che sopravvivrà, Aculeo Mentale con Eruzione Oscura, Aureola, Cascata o Stella Divina alla loro distanza ottimale, poi Flagello Mentale. Un Flagello Mentale viene interrotto per Detonazione Mentale o Parola d'Ombra: Morte, o dopo il suo secondo impulso; gli altri incanalamenti non vengono mai interrotti. In movimento suggerisce solo incantesimi istantanei. Contro cinque o più nemici: il tuo talento di sesto livello, DoT sul tuo bersaglio e Risonanza Mentale. Promemoria: Forma d'Ombra, Fuoco Interiore, Fermezza, Silenzio sui lanci interrompibili, Spirito d'Ombra o Plagiamente e Infusione di Potere nei combattimenti lunghi, Abbraccio Vampirico, Preghiera Disperata e Dispersione quando sei in difficoltà. Lasciati a te: i DoT su altri bersagli e dove cade Risonanza Mentale."
L["rm.mop.priest.shadow.warcrafttavern.Name"] = "Senza priorità di Pazzia (Warcraft Tavern)"
L["rm.mop.priest.shadow.warcrafttavern.Description"] = "Disattivata per impostazione predefinita. L'ordine Ombra di Warcraft Tavern: Piaga Divoratrice a tre Globi dell'Ombra, Parola d'Ombra: Morte sotto il 20%, Detonazione Mentale, Tocco Vampirico, Parola d'Ombra: Dolore, Aculeo Mentale con Eruzione Oscura, il tuo talento di sesto livello, Flagello Mentale. A differenza della rotazione integrata Ombra consigliata non anticipa mai Flagello Mentale durante Piaga Divoratrice e non trattiene Piaga Divoratrice per Detonazione Mentale. Stessi passaggi per apertura, movimento, gruppi di nemici e promemoria; per usarla attivala e disattiva quella consigliata."
L["rm.mop.priest.unspecialized.Name"] = "Senza specializzazione"
L["rm.mop.priest.unspecialized.Description"] = "Per i livelli da 1 a 9, o per qualsiasi sacerdote che non ha ancora scelto una specializzazione. Su un nemico: Parola d'Ombra: Dolore quando sopravvivrà abbastanza a lungo, poi Punizione. Su un alleato: Cura Rapida quando è basso di salute, altrimenti Parola del Potere: Scudo. Promemoria: Fuoco Interiore, e uno scudo su di te quando giochi da solo e sei ferito. Scegliere una specializzazione al livello 10 passa alla sua rotazione integrata."
L["rm.retail.priest.discipline.Name"] = "Espiazione (Icy Veins)"
L["rm.retail.priest.discipline.Description"] = "Disciplina in Midnight, a titolo di riferimento: l'Assistente di Combattimento di Blizzard non copre i guaritori, il gioco nasconde la salute di tutti in combattimento e Rotation Master sceglie un incantesimo, non un bersaglio, quindi questa rotazione esegue i danni che curano tramite Espiazione e lascia a te la decisione su chi curare. Su un bersaglio amico: Parola del Potere: Scudo (Scudo del Vuoto), Penitenza, Cura Rapida. Su un nemico: Parola d'Ombra: Dolore quando non l'hai lanciata da 12 secondi, Detonazione Mentale, Penitenza, Scudo, Parola d'Ombra: Morte, Detonazione del Vuoto, Punizione. Promemoria in combattimento: Parola del Potere: Radiosità, Evangelismo, Penitenza Definitiva, Soppressione del Dolore su un bersaglio amico; Fermezza tra un ingaggio e l'altro. Preghiera Disperata spetta a te. Il tempismo delle preparazioni dell'incursione prima dei danni pesanti spetta a te."
L["rm.retail.priest.discipline.wowhead.Name"] = "Morte per prima, riferimento (Wowhead)"
L["rm.retail.priest.discipline.wowhead.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine Oracolo della Stagione 1 di Wowhead, che mantiene attiva Parola d'Ombra: Dolore leggendo la penalità che Midnight nasconde in combattimento. Parola d'Ombra: Dolore, Parola d'Ombra: Morte appena pronta, Contrizione, Detonazione Mentale, Punizione; Contrizione per prima su un bersaglio amico. Stessi promemoria della rotazione integrata Icy Veins."
L["rm.retail.priest.holy.Name"] = "Icy Veins"
L["rm.retail.priest.holy.Description"] = "Sacro in Midnight, a titolo di riferimento: il gioco nasconde la salute di tutti in combattimento e Rotation Master sceglie un incantesimo, non un bersaglio, quindi questa rotazione fa girare le tue Parole Sacre, Preghiera di Guarigione e i proc su qualunque bersaglio tu abbia e lascia a te la scelta delle priorità di cura. Su un bersaglio amico: Parola Sacra: Santificazione, Parola Sacra: Serenità, Preghiera di Guarigione, Preghiera di Cura con Eruzione di Luce, Grazia Divina, Preghiera di Cura con Tessitura della Luce, Cura Rapida con Eruzione di Luce, Preghiera di Cura in gruppo, Esplosione Sacra in movimento, Cura Rapida. Su un nemico: Parola Sacra: Castigo, Fuoco Sacro, Esplosione Sacra in movimento, Punizione. Promemoria: Apoteosi, Inno Divino e Aureola in combattimento, Spirito Custode su un bersaglio amico (la salute è nascosta su Retail, quindi decidi tu se sta per morire), Fermezza. Preghiera Disperata spetta a te."
L["rm.retail.priest.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.priest.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Sacerdote). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Sacerdote condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.priest.shadow.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.priest.shadow.Description"] = "Consigliata per Ombra in Midnight. In combattimento il gioco ora nasconde agli addon i tuoi danni periodici, gli effetti benefici, i tempi di recupero e la salute, quindi questa rotazione mostra il suggerimento stesso dell'Assistente di Combattimento di Blizzard (la rotazione a un pulsante, che mantiene i tuoi danni periodici, Forma d'Ombra e Forma del Vuoto e lascia completare Flagello Mentale), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Infusione di Potere nei 20 secondi dopo aver lanciato Forma del Vuoto, Forma d'Ombra e Parola del Potere: Fermezza tra un ingaggio e l'altro, Silenzio su un lancio interrompibile (si illumina solo dove il gioco permette di leggere il lancio). La salute è nascosta su Retail, quindi Preghiera Disperata spetta a te."
L["rm.retail.priest.shadow.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.priest.shadow.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft legge i timer dei danni periodici, Follia e Forma del Vuoto, che Midnight nasconde in combattimento; Pazzia e salute sono nascoste su Retail, quindi Follia al massimo di Pazzia, l'esecuzione con Parola d'Ombra: Morte e Preghiera Disperata spettano a te. Tocco Vampirico prima dell'ingaggio; Schiaffo del Tentacolo per applicare Tocco Vampirico; Tocco Vampirico e Parola d'Ombra: Dolore rinnovati nell'ultimo 30% della loro durata; Parola d'Ombra: Follia quando sta finendo o durante Forma del Vuoto; Detonazione del Vuoto durante Follia; Schiaffo del Tentacolo a due cariche; Torrente del Vuoto; Detonazione Mentale; Schiaffo del Tentacolo; Flagello Mentale: Pazzia durante Follia; Raffica del Vuoto; Morte e Dolore in movimento; Flagello Mentale, interrotto per una Detonazione Mentale pronta. Promemoria: Aureola, Forma del Vuoto con entrambi i danni periodici attivi, Infusione di Potere durante Forma del Vuoto."
L["rm.sod.priest.dps.Name"] = "Danni (SoD)"
L["rm.sod.priest.dps.Description"] = "Danni sui reami della Season of Discovery, dal livello 1 al 60, con le rune che hai inciso. Forma d'Ombra; Tocco Vampirico o Detonazione Mentale per ingaggiare (Penitenza, Fuoco Sacro o Punizione prima di Forma d'Ombra). Piaga del Vuoto, Parola d'Ombra: Dolore e Tocco Vampirico sempre attivi (rinnovati verso la fine solo senza Dolore e Sofferenza inciso), Detonazione Mentale appena pronta, Flagello Mentale con Volti Fusi, Parola d'Ombra: Morte finché sei sopra metà della salute, poi Aculeo Mentale come riempitivo, o Flagello Mentale con il set da sei pezzi della Fase 8. Zona del Vuoto e Risonanza Mentale contro quattro o più nemici. La bacchetta su un bersaglio in punto di morte quando giochi da solo. Promemoria: Fuoco Interiore, Fermezza, Omuncoli, Spirito d'Ombra, Occhio del Vuoto e Dispersione, Concentrazione Interiore, Urlo Psichico, Trasparenza, Preghiera Disperata."
L["rm.sod.priest.dps.wowhead.Name"] = "Danni (SoD, cumuli di Aculeo Mentale di Wowhead)"
L["rm.sod.priest.dps.wowhead.Description"] = "Il metodo di Wowhead e Warcraft Tavern per la Season of Discovery, un'alternativa alla rotazione integrata consigliata di danni della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Detonazione Mentale aspetta tre dei tuoi cumuli di Aculeo Mentale sul bersaglio (viene lanciata normalmente finché non incidi Aculeo Mentale), Flagello Mentale solo con Volti Fusi, Aculeo Mentale come riempitivo. Tutto il resto corrisponde alla rotazione integrata consigliata."
L["rm.sod.priest.healer.Name"] = "Guaritore (SoD)"
L["rm.sod.priest.healer.Description"] = "Scelta sui reami della Season of Discovery in gruppo quando Sacro o Disciplina è il tuo albero dei talenti principale; segue Icy Veins. Cura l'unità amica che hai come bersaglio: Preghiera di Guarigione prima dell'ingaggio e ogni volta che è pronta, Scudo sotto metà della salute, Contrizione, Cura Rapida istantanea con Eruzione di Luce, Cura Rapida d'emergenza, dissoluzioni, Circolo di Guarigione e Preghiera di Cura quando tre membri del tuo gruppo sono feriti, Cura Maggiore sotto metà della salute, Rinnovamento in movimento o con danni leggeri, poi Cura. Un bersaglio nemico riceve Dolore, Piaga del Vuoto, Contrizione, Fuoco Sacro e Punizione. I promemoria includono Spirito d'Ombra, Soppressione del Dolore su un bersaglio in punto di morte, Parola del Potere: Barriera e Spirito del Redentore quando il gruppo è ferito."
L["rm.sod.priest.healer.warcrafttavern.Name"] = "Guaritore (SoD, Warcraft Tavern)"
L["rm.sod.priest.healer.warcrafttavern.Description"] = "Il ciclo di Provvidenza di Warcraft Tavern, ideale con Provvidenza e Protezione dell'Anima, un'alternativa alla rotazione integrata consigliata da guaritore della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Preghiera di Guarigione appena pronta, Scudo sul tuo bersaglio ogni volta che può riceverne uno (con Protezione dell'Anima inciso; altrimenti sotto metà della salute), Penitenza con danni pesanti, Circolo di Guarigione per tre feriti, Cura Superiore o Preghiera di Cura a tre cumuli di Provvidenza, Rinnovamento con danni minori, e Cura Rapida su ferite lievi per accumulare i cumuli (con Provvidenza inciso; altrimenti sotto il 30%)."
L["rm.tbc.priest.dps.icyveins.Name"] = "Danni (Icy Veins)"
L["rm.tbc.priest.dps.icyveins.Description"] = "Danni dal livello 1 al 70, usata ogni volta che la rotazione integrata da guaritore non si applica. All'inizio Punizione e bacchetta, poi Detonazione Mentale, Parola d'Ombra: Dolore, Flagello Mentale, Forma d'Ombra, Tocco Vampirico e Parola d'Ombra: Morte man mano che li apprendi; i danni periodici prima di Detonazione Mentale; da solo, un bersaglio in punto di morte viene finito con la bacchetta. Chi completa missioni come Sacro o Disciplina riceve Fuoco Sacro e Punizione. Promemoria: Fuoco Interiore, Fermezza, effetti benefici razziali, Concentrazione Interiore, Spirito d'Ombra. Un Flagello Mentale oltre il primo impulso viene interrotto per una Detonazione Mentale pronta, o per Parola d'Ombra: Morte sopra metà salute. Scudi e cure restano a te."
L["rm.tbc.priest.dps.wowhead.Name"] = "Danni (Wowhead)"
L["rm.tbc.priest.dps.wowhead.Description"] = "Danni secondo le guide di Wowhead, un'alternativa alla rotazione integrata consigliata da danni di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Detonazione Mentale apre e viene prima del rinnovo dei danni periodici, Abbraccio Vampirico solo quando la tua salute cala, e un bersaglio in punto di morte riceve incantesimi invece della bacchetta. Per il resto è uguale alla rotazione integrata consigliata."
L["rm.tbc.priest.healer.icyveins.Name"] = "Guaritore (Icy Veins)"
L["rm.tbc.priest.healer.icyveins.Description"] = "Cure secondo l'ordine di Icy Veins: Scudo, dissoluzioni, Cura Combinata, Rinnovamento, Cura Rapida, Cura Superiore (qualsiasi grado), cure di gruppo e per ultima Preghiera di Guarigione. Scegli tu chi curare. Un'alternativa alla rotazione integrata consigliata da guaritore di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.tbc.priest.healer.wowhead.Name"] = "Guaritore (Wowhead)"
L["rm.tbc.priest.healer.wowhead.Description"] = "Cure in gruppo quando Sacro o Disciplina è il tuo albero dei talenti principale. Consiglia in base all'unità amica che hai come bersaglio; scegli tu chi curare. Preghiera di Guarigione prima degli ingaggi e ogni volta che è pronta, Rinnovamento, Parola del Potere: Scudo nelle emergenze, dissoluzioni, Cerchio di Guarigione o Preghiera di Cura per i danni al gruppo, Cura Combinata, Cura Rapida e Cura Superiore, e Cura Superiore di grado 1 come rabbocco economico. Con un nemico come bersaglio propone qualche danno leggero."
